actions.script:
for (let size = 0; size !== classIdList.length; ) {
                size = classIdList.length
                for (const row of classList)
                    if (classIdList.includes(row.parentEnumId) && !classIdList.includes(row.enumId))
                        classIdList.push(row.enumId)
            }
